<script setup>
import {Link,router} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';const props=defineProps({items:Array,total:Number});const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);const update=(item,e)=>router.patch(`/keranjang/${item.product.id}`,{qty:Number(e.target.value)});const remove=item=>router.delete(`/keranjang/${item.product.id}`);
</script>
<template><AppLayout><div class="page"><h1 class="page-title">Keranjang Belanja</h1><div v-if="!items.length" class="panel" style="text-align:center;padding:45px"><div style="font-size:50px">🛒</div><h3>Keranjang kamu masih kosong</h3><Link href="/" class="btn">Mulai Belanja</Link></div><div v-else class="panel"><table class="table"><thead><tr><th>Produk</th><th>Harga</th><th>Jumlah</th><th>Subtotal</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.product.id"><td><strong>{{item.product.name}}</strong></td><td>{{money(item.product.price)}}</td><td><input class="qty" type="number" min="0" :max="item.product.stock" :value="item.qty" @change="update(item,$event)"></td><td>{{money(item.subtotal)}}</td><td><button class="btn danger" @click="remove(item)">Hapus</button></td></tr></tbody></table><div class="between" style="margin-top:25px"><Link href="/" class="btn light">Lanjut Belanja</Link><div style="text-align:right"><div class="muted">Total Belanja</div><div class="price">{{money(total)}}</div><Link href="/checkout" class="btn">Lanjut Checkout →</Link></div></div></div></div></AppLayout></template>
